fn solve_easy() {
    let plain_part = "";
    let cipher = "";

    let solver = EnigmaSolver::new(cipher, plain_part);
    let settings = solver.known_plain_text_cipher_break();

    let Some(settings) = settings else {
        error!("Unable to break cipher!!!");
        return;
    };

    println!("Enigma Settings Solution: {settings:#?}");
    println!(
        "Deciphered text: {}",
        Enigma::from(settings).encrypt_str(cipher).unwrap()
    )
}
